'use client';
import React, { useRef, useState } from 'react';

import * as Picker from 'emoji-picker-react/primitives';


export type ShellProps = { Root?: React.ElementType; className?: string };

function Hint() {
  const active = Picker.useActiveEmoji();
  const { search } = Picker.useSearchState();
  return <div className="typeahead-hint">
    <span className="typeahead-name">{active ? active.names[active.names.length - 1] : `Emoji matching “${search}”`}</span>
    <span>↵ insert · esc dismiss</span>
  </div>;
}

// Name autocomplete triggered by ':', not a Slack shortcode resolver.
export function Shell({ Root: RootComponent = Picker.Root, className }: ShellProps) {
  const [text, setText] = useState('Shipped the fix to production :party');
  const [caret, setCaret] = useState(text.length);
  const [dismissed, setDismissed] = useState(false);
  const input = useRef<HTMLTextAreaElement>(null);
  const picker = useRef<HTMLDivElement>(null);
  const match = /(?:^|\s):([^\s:]+)$/.exec(text.slice(0, caret));
  const query = match?.[1] ?? '';
  const open = !!query && !dismissed;

  function insert(emoji: Picker.EmojiClickData) {
    const start = caret - query.length - 1;
    const nextCaret = start + emoji.emoji.length;
    setText(text.slice(0, start) + emoji.emoji + text.slice(caret));
    setCaret(nextCaret);
    setDismissed(true);
    requestAnimationFrame(() => {
      input.current?.focus();
      input.current?.setSelectionRange(nextCaret, nextCaret);
    });
  }

  return <div className="typeahead-card" onKeyDown={(event) => {
    if (event.key === 'Escape' && open) {
      event.preventDefault(); setDismissed(true); input.current?.focus();
    }
  }}>
    <p className="typeahead-label">Reply to #142</p>
    <textarea ref={input} className="typeahead-box" rows={1} aria-label="Reply"
      value={text}
      onChange={(event) => {
        setText(event.target.value); setCaret(event.target.selectionStart); setDismissed(false);
      }}
      onSelect={(event) => setCaret(event.currentTarget.selectionStart)}
      onKeyDown={(event) => {
        if (open && event.key === 'ArrowDown') {
          const first = Array.from(picker.current?.querySelectorAll<HTMLButtonElement>('[role="gridcell"]') ?? [])
            .find((cell) => cell.getClientRects().length > 0);
          if (first) { event.preventDefault(); first.focus(); }
        }
      }} />
    {open && <div ref={picker}>
      <RootComponent className={className} searchValue={query}
        skinTonePickerLocation={Picker.SkinTonePickerLocation.NONE}
        autoFocusSearch={false} onEmojiClick={insert}>
        <Picker.Viewport><Picker.List /><Picker.Empty /></Picker.Viewport>
        <Hint />
      </RootComponent>
    </div>}
  </div>;
}

/* The host app around the picker (shared by every stack variant). */
.typeahead-card {
  width: 480px;
  height: 330px;
  padding: 20px;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  background: #ffffff;
  color: #111827;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.typeahead-label {
  margin: 0 0 8px;
  color: #4b5563;
  font-size: 13px;
  font-weight: 600;
}
.typeahead-box {
  display: block;
  box-sizing: border-box;
  width: 100%;
  resize: none;
  font: inherit;
  color: inherit;
  background: #fff;
  padding: 12px 14px;
  border: 2px solid #2563eb;
  border-radius: 10px;
  font-size: 15px;
}
.typeahead-caret {
  display: inline-block;
  width: 2px;
  height: 18px;
  margin-left: 1px;
  vertical-align: text-bottom;
  background: #2563eb;
}

/* Shortcode typeahead — an autocomplete dropdown: results only, a hint
   footer driven by useActiveEmoji(). */
.typeahead-picker {
  --epr-bg-color: #ffffff;
  --epr-text-color: #4b5563;
  --epr-highlight-color: #2563eb;
  --epr-hover-bg-color: #eff6ff;
  --epr-focus-bg-color: #dbeafe;
  --epr-category-label-height: 0px;
  --epr-emoji-size: 28px;
  --epr-emoji-padding: 6px;
  --epr-horizontal-padding: 8px;
  width: 340px;
  height: 172px;
  margin-top: 6px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgb(17 24 39 / 14%);
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.typeahead-picker [data-epr-part='category-label'] {
  display: none;
}
.typeahead-picker [data-epr-part='list'] {
  padding-top: 6px;
}
.typeahead-picker [data-epr-part='emoji'] {
  border-radius: 8px;
}
.typeahead-picker .typeahead-hint {
  display: flex;
  justify-content: space-between;
  padding: 8px 12px;
  border-top: 1px solid #f3f4f6;
  color: #4b5563;
  font-size: 12px;
}
.typeahead-picker .typeahead-name::first-letter {
  text-transform: uppercase;
}

/* Generated by scripts/generateRecipes.mjs from picker.css — do not edit. */
.picker {
  --epr-bg-color: #ffffff;
  --epr-text-color: #4b5563;
  --epr-highlight-color: #2563eb;
  --epr-hover-bg-color: #eff6ff;
  --epr-focus-bg-color: #dbeafe;
  --epr-category-label-height: 0px;
  --epr-emoji-size: 28px;
  --epr-emoji-padding: 6px;
  --epr-horizontal-padding: 8px;
  width: 340px;
  height: 172px;
  margin-top: 6px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgb(17 24 39 / 14%);
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.picker [data-epr-part='category-label'] {
  display: none;
}
.picker [data-epr-part='list'] {
  padding-top: 6px;
}
.picker [data-epr-part='emoji'] {
  border-radius: 8px;
}
.picker :global(.typeahead-hint) {
  display: flex;
  justify-content: space-between;
  padding: 8px 12px;
  border-top: 1px solid #f3f4f6;
  color: #4b5563;
  font-size: 12px;
}
.picker :global(.typeahead-name)::first-letter {
  text-transform: uppercase;
}
